namespace sv_af4799e9f66841bf8fe55b1f84f6f6b3.Services;

public record Product(int Id, string Name, decimal Price, string Category, double Rating, bool InStock, string ImageUrl);
public record ProductFilter(List<string>? Categories, decimal? MinPrice, decimal? MaxPrice, bool InStockOnly);
public record PagedResult<T>(List<T> Items, int TotalCount, int Page, int PageSize);

public interface IProductService
{
    Task<PagedResult<Product>> SearchAsync(ProductFilter filter, string sortBy, int page, int pageSize);
    Task<List<string>> GetCategoriesAsync();
}

@page "/catalog"
@using sv_af4799e9f66841bf8fe55b1f84f6f6b3.Services
@inject IProductService ProductService
@rendermode InteractiveServer

<PageTitle>Product Catalog</PageTitle>

<div class="container-fluid">
    <h1 class="mb-4">Product Catalog</h1>

    @if (_error is not null)
    {
        <div class="alert alert-danger" role="alert">
            <strong>Error:</strong> @_error
            <button class="btn btn-sm btn-outline-danger ms-3" @onclick="RetryAsync">Retry</button>
        </div>
    }
    else
    {
        <div class="row">
            @* ── Left Sidebar (Filters) ── *@
            <div class="col-lg-3 mb-4">
                <div class="card">
                    <div class="card-header fw-semibold">Filters</div>
                    <div class="card-body">
                        @* Categories *@
                        <h6>Category</h6>
                        @if (_categories is null)
                        {
                            <p class="text-muted small">Loading categories…</p>
                        }
                        else
                        {
                            @foreach (var cat in _categories)
                            {
                                <div class="form-check">
                                    <input class="form-check-input" type="checkbox" id="@($"cat-{cat}")"
                                           checked="@(_selectedCategories.Contains(cat))"
                                           @onchange="e => ToggleCategory(cat, (bool)e.Value!)" />
                                    <label class="form-check-label" for="@($"cat-{cat}")">@cat</label>
                                </div>
                            }
                        }

                        <hr />

                        @* Price Range *@
                        <h6>Price Range</h6>
                        <div class="mb-2">
                            <label class="form-label small" for="minPrice">Min Price</label>
                            <input id="minPrice" type="number" class="form-control form-control-sm"
                                   min="0" step="0.01" placeholder="0.00"
                                   @bind="_minPrice" @bind:event="oninput" />
                        </div>
                        <div class="mb-3">
                            <label class="form-label small" for="maxPrice">Max Price</label>
                            <input id="maxPrice" type="number" class="form-control form-control-sm"
                                   min="0" step="0.01" placeholder="Any"
                                   @bind="_maxPrice" @bind:event="oninput" />
                        </div>

                        <hr />

                        @* In Stock Only *@
                        <div class="form-check form-switch mb-3">
                            <input class="form-check-input" type="checkbox" id="inStockOnly"
                                   @bind="_inStockOnly" />
                            <label class="form-check-label" for="inStockOnly">In Stock Only</label>
                        </div>

                        @* Action Buttons *@
                        <div class="d-grid gap-2">
                            <button class="btn btn-primary" @onclick="ApplyFiltersAsync" disabled="@_loading">
                                Apply Filters
                            </button>
                            <button class="btn btn-outline-secondary" @onclick="ClearFiltersAsync" disabled="@_loading">
                                Clear Filters
                            </button>
                        </div>
                    </div>
                </div>
            </div>

            @* ── Main Content Area ── *@
            <div class="col-lg-9">
                @* Toolbar *@
                <div class="d-flex justify-content-between align-items-center mb-3 flex-wrap gap-2">
                    <div class="d-flex align-items-center gap-2">
                        <label class="form-label mb-0 fw-semibold" for="sortBy">Sort by:</label>
                        <select id="sortBy" class="form-select form-select-sm" style="width: auto;"
                                @bind="_sortBy" @bind:after="OnSortChangedAsync">
                            <option value="price_asc">Price: Low to High</option>
                            <option value="price_desc">Price: High to Low</option>
                            <option value="name_asc">Name: A–Z</option>
                            <option value="rating_desc">Rating: Highest</option>
                        </select>
                    </div>

                    @if (_result is not null)
                    {
                        var first = (_result.Page - 1) * _result.PageSize + 1;
                        var last = Math.Min(_result.Page * _result.PageSize, _result.TotalCount);
                        <span class="text-muted">Showing @first–@last of @_result.TotalCount products</span>
                    }
                </div>

                @* Loading State *@
                @if (_loading)
                {
                    <div class="text-center py-5">
                        <div class="spinner-border text-primary" role="status">
                            <span class="visually-hidden">Loading…</span>
                        </div>
                        <p class="mt-2 text-muted">Loading products…</p>
                    </div>
                }
                @* Empty State *@
                else if (_result is not null && _result.Items.Count == 0)
                {
                    <div class="text-center py-5">
                        <h4 class="text-muted">No products found</h4>
                        <p class="text-muted">Try adjusting your filters or clearing them.</p>
                        <button class="btn btn-outline-primary" @onclick="ClearFiltersAsync">Clear Filters</button>
                    </div>
                }
                @* Product Grid *@
                else if (_result is not null)
                {
                    <div class="row row-cols-1 row-cols-sm-2 row-cols-md-3 g-4">
                        @foreach (var product in _result.Items)
                        {
                            <div class="col">
                                <div class="card h-100 product-card" @onclick="() => OnProductSelected.InvokeAsync(product.Id)"
                                     style="cursor: pointer;">
                                    <div class="card-img-top bg-light d-flex align-items-center justify-content-center"
                                         style="height: 180px;" role="img" aria-label="@product.Name">
                                        <span class="text-muted">@product.Name</span>
                                    </div>
                                    <div class="card-body d-flex flex-column">
                                        <h6 class="card-title">@product.Name</h6>
                                        <p class="card-text fw-bold text-primary mb-1">@product.Price.ToString("C")</p>
                                        <p class="card-text mb-2">
                                            <span class="text-warning">@GetStarRating(product.Rating)</span>
                                        </p>
                                        @if (!product.InStock)
                                        {
                                            <span class="badge bg-danger mb-2">Out of Stock</span>
                                        }
                                        <button class="btn btn-sm btn-success mt-auto"
                                                disabled="@(!product.InStock)"
                                                @onclick="() => { }" @onclick:stopPropagation="true">
                                            Add to Cart
                                        </button>
                                    </div>
                                </div>
                            </div>
                        }
                    </div>

                    @* Pagination *@
                    @if (TotalPages > 1)
                    {
                        <nav class="mt-4" aria-label="Product pagination">
                            <ul class="pagination justify-content-center">
                                <li class="page-item @(_currentPage <= 1 ? "disabled" : "")">
                                    <button class="page-link" @onclick="() => GoToPageAsync(_currentPage - 1)"
                                            disabled="@(_currentPage <= 1)">Previous</button>
                                </li>
                                @for (var i = 1; i <= TotalPages; i++)
                                {
                                    var page = i;
                                    <li class="page-item @(page == _currentPage ? "active" : "")">
                                        <button class="page-link" @onclick="() => GoToPageAsync(page)">@page</button>
                                    </li>
                                }
                                <li class="page-item @(_currentPage >= TotalPages ? "disabled" : "")">
                                    <button class="page-link" @onclick="() => GoToPageAsync(_currentPage + 1)"
                                            disabled="@(_currentPage >= TotalPages)">Next</button>
                                </li>
                            </ul>
                        </nav>
                    }
                }
            </div>
        </div>
    }
</div>

@code {
    [Parameter] public EventCallback<int> OnProductSelected { get; set; }

    private const int PageSize = 12;

    private List<string>? _categories;
    private HashSet<string> _selectedCategories = new();
    private decimal? _minPrice;
    private decimal? _maxPrice;
    private bool _inStockOnly;
    private string _sortBy = "price_asc";
    private int _currentPage = 1;

    private PagedResult<Product>? _result;
    private bool _loading;
    private string? _error;

    private int TotalPages => _result is null || _result.PageSize == 0
        ? 1
        : (int)Math.Ceiling((double)_result.TotalCount / _result.PageSize);

    protected override async Task OnInitializedAsync()
    {
        await LoadInitialDataAsync();
    }

    private async Task LoadInitialDataAsync()
    {
        _loading = true;
        _error = null;

        try
        {
            var categoriesTask = ProductService.GetCategoriesAsync();
            var searchTask = SearchProductsAsync();

            _categories = await categoriesTask;
            await searchTask;
        }
        catch (Exception ex)
        {
            _error = $"Failed to load catalog: {ex.Message}";
        }
        finally
        {
            _loading = false;
        }
    }

    private async Task SearchProductsAsync()
    {
        var filter = new ProductFilter(
            Categories: _selectedCategories.Count > 0 ? _selectedCategories.ToList() : null,
            MinPrice: _minPrice,
            MaxPrice: _maxPrice,
            InStockOnly: _inStockOnly
        );

        _result = await ProductService.SearchAsync(filter, _sortBy, _currentPage, PageSize);
    }

    private async Task ApplyFiltersAsync()
    {
        _currentPage = 1;
        _loading = true;
        _error = null;

        try
        {
            await SearchProductsAsync();
        }
        catch (Exception ex)
        {
            _error = $"Search failed: {ex.Message}";
        }
        finally
        {
            _loading = false;
        }
    }

    private async Task ClearFiltersAsync()
    {
        _selectedCategories.Clear();
        _minPrice = null;
        _maxPrice = null;
        _inStockOnly = false;
        _currentPage = 1;
        _sortBy = "price_asc";

        await ApplyFiltersAsync();
    }

    private async Task OnSortChangedAsync()
    {
        _currentPage = 1;
        await ApplyFiltersAsync();
    }

    private async Task GoToPageAsync(int page)
    {
        if (page < 1 || page > TotalPages) return;

        _currentPage = page;
        _loading = true;
        _error = null;

        try
        {
            await SearchProductsAsync();
        }
        catch (Exception ex)
        {
            _error = $"Failed to load page: {ex.Message}";
        }
        finally
        {
            _loading = false;
        }
    }

    private async Task RetryAsync() => await LoadInitialDataAsync();

    private void ToggleCategory(string category, bool selected)
    {
        if (selected)
            _selectedCategories.Add(category);
        else
            _selectedCategories.Remove(category);
    }

    private static string GetStarRating(double rating)
    {
        var rounded = (int)Math.Round(rating);
        return new string('★', rounded) + new string('☆', 5 - rounded);
    }
}

